    @Test
    @Order(7)
    void shouldCancelConfirmedReservationWithRefund() throws Exception {
        String json = """
            {
                "roomNumber": "202",
                "guestName": "Ana Costa",
                "guestEmail": "ana@example.com",
                "guestCpf": "22222222222",
                "checkIn": "2027-04-01",
                "checkOut": "2027-04-03",
                "guests": 2,
                "ratePlan": "STANDARD"
